<?php
namespace Modules\Ran\Http\Controllers;use Illuminate\Http\Request;use Modules\Ran\Services\ReportRegistry;
class ReportController extends RanController{public function index(ReportRegistry $r){return view('ran::reports.index',['reports'=>$r->map()]);}public function show(Request $request,string $report,ReportRegistry $registry){$filters=$request->only(['date_from','date_to','location_id','store_id']);$instance=$registry->get($report);$rows=$instance->rows($filters);return view('ran::reports.show',array_merge($this->pageOptions(),['reportKey'=>$report,'report'=>$instance,'rows'=>$rows,'totals'=>$instance->totals($rows),'filters'=>$filters]));}public function csv(Request $request,string $report,ReportRegistry $registry){$instance=$registry->get($report);$rows=$instance->rows($request->only(['date_from','date_to','location_id','store_id']));return response()->streamDownload(function()use($instance,$rows){$h=fopen('php://output','w');fputcsv($h,$instance->headings());foreach($rows as $row)fputcsv($h,array_values($row));fclose($h);},'ran-'.$report.'-'.now()->format('Ymd-His').'.csv',['Content-Type'=>'text/csv']);}}
